117	+/// Each `ToolCall` has a `ToolResult` with the same call id later, with no
118	+/// `UserMessage` or `AssistantMessage` between them. Each `ToolResult` closes
119	+/// one earlier open `ToolCall` with its call id. A call id can repeat only
120	+/// after its earlier call has a result. A call after a result starts a new
121	+/// round, so no call may wait for a result then.
122	+///
123	+/// A copy is in `crates/paigasus-helikon-runtime-tokio/tests/deferred.rs`.
124	+/// Keep the two copies the same.
125	+pub fn assert_tool_calls_paired(messages: &[Item]) {
126	+    // The calls that wait for a result, in call order.
127	+    let mut outstanding: Vec<&str> = Vec::new();
128	+    // A result came after the last call: the next call starts a new round.
129	+    let mut seen_result_since_call = false;
130	+    for item in messages {
131	+        match item {
132	+            Item::ToolCall { call_id, .. } => {
133	+                assert!(
134	+                    !outstanding.contains(&call_id.as_str()),
135	+                    "call {call_id} repeats while it waits for a result: {messages:?}"
136	+                );
137	+                assert!(
138	+                    !(seen_result_since_call && !outstanding.is_empty()),
139	+                    "call {call_id} starts a new round while {outstanding:?} wait for a result: {messages:?}"
140	+                );
141	+                seen_result_since_call = false;
142	+                outstanding.push(call_id);
143	+            }
144	+            Item::ToolResult { call_id, .. } => {
145	+                let Some(p) = outstanding.iter().position(|c| *c == call_id.as_str()) else {
146	+                    panic!("result {call_id} has no open earlier call: {messages:?}");
147	+                };
148	+                // Each result closes one call.
149	+                outstanding.remove(p);
150	+                seen_result_since_call = true;
151	+            }
152	+            Item::UserMessage { .. } | Item::AssistantMessage { .. } => {
153	+                assert!(
154	+                    outstanding.is_empty(),
155	+                    "tool calls {outstanding:?} are not paired: {messages:?}"
156	+                );
157	+            }
158	+            _ => {}
159	+        }
160	+    }
161	+    assert!(
162	+        outstanding.is_empty(),
163	+        "tool calls {outstanding:?} are not paired: {messages:?}"
164	+    );
165	+}
